// ---------------------------------------------------------------------------
// One Gmail message -> the shape /ingest accepts.
//
// This file is plumbing. It does not decide whether an email is an offer or a
// request, what a row means, or what anything costs — all of that is Python,
// where it is tested. If you find yourself adding a rule about the trade here,
// it belongs on the other side of the wire.
// ---------------------------------------------------------------------------

const TENANT_ID = $env.TVD_TENANT_ID || 'b9316981-b732-4891-854f-3335205dd582';

// Reply quoting only. NOT forwarded messages: the client's whole workflow is
// forwarding a supplier's email to himself, so the payload sits below
// 'Begin forwarded message' and cutting there would delete the email.
// The backend strips again and refuses any cut that would remove the prices,
// so this being imperfect is survivable.
const REPLY = [
  /^\s*(?:On|Am|Le|Il|El)\b[^\n]{0,160}\b(?:wrote|schrieb|a écrit|ha scritto):\s*$/im,
  /^\s*-{2,}\s*Original Message\s*-{2,}/im,
  /^>[^\n]*\n>[^\n]*\n>/m,
];
const FORWARD = /-{2,}\s*Forwarded message\s*-{2,}|Begin forwarded message/i;

function stripQuoted(body) {
  if (!body) return '';
  let cut = null;
  for (const pattern of REPLY) {
    const found = body.match(pattern);
    if (found && (cut === null || found.index < cut)) cut = found.index;
  }
  if (cut === null) return body;
  if (FORWARD.test(body.slice(cut))) return body;   // the forward is the point
  return body.slice(0, cut).trimEnd();
}

function address(raw) {
  const found = String(raw || '').match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
  return found ? found[0].toLowerCase() : '';
}

function header(message, name) {
  const headers = message.payload?.headers || message.headers || [];
  const hit = headers.find((h) => String(h.name).toLowerCase() === name);
  return hit ? hit.value : (message[name] || '');
}

const out = [];

for (const item of $input.all()) {
  const message = item.json;

  // Message-ID is what /ingest deduplicates on. Gmail's own id is a fallback:
  // without something stable, a redelivery reconciles a second time and every
  // row missing from the second copy is closed as sold.
  const messageId =
    header(message, 'message-id') || `<gmail-${message.id}@tvd.local>`;

  const text = message.text || message.textPlain || '';
  const html = message.textHtml || message.textAsHtml || '';

  // Spreadsheet rows come from the Extract node, which emits one item per sheet
  // row. Grouped back into a grid here; the header row is included because the
  // parser scores rows to find it rather than assuming row 1.
  const rows = [];
  for (const sheetItem of $('Read any spreadsheets').all()) {
    const values = Object.values(sheetItem.json).map((v) => (v === null || v === undefined ? '' : String(v)));
    if (values.some((v) => v.trim() !== '')) rows.push(values);
  }

  const attachments = [];
  const binaries = item.binary || {};
  for (const key of Object.keys(binaries)) {
    const file = binaries[key];
    const name = file.fileName || key;
    const isSheet = /\.(xlsx|xlsm|xls|csv)$/i.test(name);
    attachments.push({
      filename: name,
      mime_type: file.mimeType || '',
      kind: isSheet && rows.length ? 'table' : 'other',
      rows: isSheet && rows.length ? rows : null,
    });
  }

  out.push({
    json: {
      tenant_id: TENANT_ID,
      message_id: messageId,
      in_reply_to: header(message, 'in-reply-to') || null,
      thread_id: message.threadId || null,
      direction: 'inbound',
      from_email: address(header(message, 'from')),
      from_name: String(header(message, 'from') || '').split('<')[0].replace(/"/g, '').trim(),
      to: [address(header(message, 'to'))].filter(Boolean),
      subject: header(message, 'subject') || '',
      received_at: new Date(Number(message.internalDate) || Date.now()).toISOString(),
      // What gets parsed.
      body_text: stripQuoted(text || html.replace(/<[^>]+>/g, ' ')),
      // The complete original, for the source drawer. Never parsed, so it keeps
      // its markup — that is what table extraction reads.
      body_raw: html || text,
      attachments,
    },
  });
}

return out;

for (const item of $input.all()) {
  const detail = item.json.detail || '(no detail)';
  console.log(`${item.json.message_id} -> ${detail}`);
}
return $input.all();
